using System;using System.Reflection;using System.Linq;using System.Collections.Generic;using Emberfall;using UnityEngine;
namespace UnityEngine{
 public class Object{public bool Destroyed;public static void Destroy(Object o){if(o==null||o.Destroyed)return;o.Destroyed=true;if(o is GameObject g){g.SetActive(false);foreach(var child in g.transform.Children.ToArray())Destroy(child.gameObject);foreach(var c in g.Components)c.GetType().GetMethod("OnDestroy",BindingFlags.NonPublic|BindingFlags.Instance)?.Invoke(c,null);}}}
 public class MonoBehaviour:Object{public GameObject gameObject;public Transform transform=>gameObject.transform;}
 public class GameObject:Object{public Transform transform;public string name;public bool activeSelf=true;public readonly List<object> Components=new List<object>();public GameObject(string n=""){name=n;transform=new Transform{gameObject=this};}public void SetActive(bool v){activeSelf=v;}public T AddComponent<T>()where T:new(){var c=new T();if(c is MonoBehaviour m)m.gameObject=this;Components.Add(c);return c;}public T GetComponent<T>()where T:class=>Components.OfType<T>().FirstOrDefault();}
 public class Transform{public GameObject gameObject;public Vector3 position,localScale,forward=Vector3.forward;public Quaternion rotation;public List<Transform> Children=new List<Transform>();public int childCount=>Children.Count;public void SetParent(Transform parent,bool world){parent.Children.Add(this);}public T GetComponent<T>()where T:class=>gameObject.GetComponent<T>();}
 public struct Quaternion{public static Quaternion Euler(float x,float y,float z)=>new Quaternion();}
 public class Shader{public static Shader Find(string n)=>new Shader();}public static class Resources{public static T Load<T>(string n)where T:new()=>new T();}
 public static class ColorUtility{public static string ToHtmlStringRGBA(Color c)=>c.r+","+c.g+","+c.b+","+c.a;}
 public class Material:Object{public Color color;public Material(){}public Material(Shader s){}public bool HasProperty(string n)=>false;public void SetFloat(string n,float v){}public void SetColor(string n,Color c){}}
 public class Mesh:Object{public string name;public Vector3[] vertices;public void RecalculateBounds(){}}
 public class MeshFilter:MonoBehaviour{public Mesh sharedMesh;}
 public class Renderer:MonoBehaviour{public Material sharedMaterial;public Rendering.ShadowCastingMode shadowCastingMode;public bool receiveShadows;public MaterialPropertyBlock PropertyBlock;public void SetPropertyBlock(MaterialPropertyBlock b){PropertyBlock=new MaterialPropertyBlock();foreach(var p in b.Colors)PropertyBlock.Colors[p.Key]=p.Value;foreach(var p in b.Floats)PropertyBlock.Floats[p.Key]=p.Value;}}
 public class MeshRenderer:Renderer{}
 public class MaterialPropertyBlock{public Dictionary<string,Color> Colors=new Dictionary<string,Color>();public Dictionary<string,float> Floats=new Dictionary<string,float>();public void Clear(){Colors.Clear();Floats.Clear();}public void SetColor(string n,Color c){Colors[n]=c;}public void SetFloat(string n,float v){Floats[n]=v;}}
 public struct Color{public float r,g,b,a;public Color(float r,float g,float b,float a=1){this.r=r;this.g=g;this.b=b;this.a=a;}public static Color operator*(Color c,float f)=>new Color(c.r*f,c.g*f,c.b*f,c.a*f);public static Color Lerp(Color a,Color b,float t)=>new Color(a.r+(b.r-a.r)*t,a.g+(b.g-a.g)*t,a.b+(b.b-a.b)*t,a.a+(b.a-a.a)*t);}
 public partial struct Vector3{public static Vector3 right=>new Vector3(1,0,0);public static Vector3 forward=>new Vector3(0,0,1);public static Vector3 Scale(Vector3 a,Vector3 b)=>new Vector3(a.x*b.x,a.y*b.y,a.z*b.z);public static Vector3 Cross(Vector3 a,Vector3 b)=>new Vector3(a.y*b.z-a.z*b.y,a.z*b.x-a.x*b.z,a.x*b.y-a.y*b.x);}
 public static partial class Mathf{public static float Sqrt(float x)=>(float)Math.Sqrt(x);public static float Lerp(float a,float b,float t)=>a+(b-a)*t;}
}
