 public static partial class EnemySkillPhysicalVfx{internal static Mesh GelMesh=new Mesh{name="Shared wet gel"};private static readonly Mesh[] crusts={new Mesh{name="Shared crust 0"},new Mesh{name="Shared crust 1"},new Mesh{name="Shared crust 2"}};internal static Mesh CrustMesh(int variant)=>crusts[variant%crusts.Length];}
 public class GameSession{public static GameSession Instance;public bool InputBlocked;}
 public partial class EnemyController:MonoBehaviour{private GameObject warning;private EnemyAttackTelegraph telegraph;internal void Bind(EnemyAttackTelegraph t){telegraph=t;warning=t.gameObject;}public void CancelWarning(){ClearWarning();}public bool WarningCleared=>warning==null&&telegraph==null;}
