public static class EnemyImpactContourTests{
 static int checks;static void Check(bool okay,string why){checks++;if(!okay)throw new Exception(why);}
 static T Field<T>(object o,string name)=>(T)o.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);
 static void Call(object o,string name)=>o.GetType().GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(o,null);
 static void Bounds(EnemyAttackTelegraph w,Vector3 from,Vector3 center,float radius){
  var p=Field<List<Vector3>>(w,"points");var s=Field<List<Vector3>>(w,"scales");var b=Field<List<Transform>>(w,"bodies");Check(p.Count>0&&p.Count==s.Count&&p.Count==b.Count,"reachable lobe has real soil bodies");
  for(int i=0;i<p.Count;i++){Check(EnemyImpactRegion.Contains(from,center,p[i],radius),"body uses actual Contains");float extent=s[i].x*.74f;foreach(var d in new[]{Vector3.right*extent,Vector3.right*-extent,Vector3.forward*extent,Vector3.forward*-extent})Check(EnemyImpactRegion.Contains(from,center,p[i]+d,radius),"whole soil footprint stays inside actual impact");Check(Math.Abs(b[i].position.y-WorldTraversal.SurfaceHeight(p[i],.04f)+.025f-b[i].localScale.y*.4f)<.0001f,"soil follows actual terrain height");Check(Enumerable.Range(0,3).Any(v=>b[i].GetComponent<MeshFilter>().sharedMesh==EnemySkillPhysicalVfx.CrustMesh(v)),"solid natural crust uses the shared body cache");}
 }
 public static string Run(){
  checks=0;GameSession.Instance=null;WorldTraversal.Reset(ZoneKind.Dungeon);var a=new Transform{position=new Vector3(-2,0,0)};var center=new Vector3(.4f,0,0);float r=2;WorldTraversal.AddBox(Vector3.zero,new Vector2(.2f,7));
  Check(!EnemyImpactRegion.Contains(a.position,center,center,r),"center behind wall can retain reachable near lobe");var w=EnemyAttackTelegraph.Circle(center,r,a);var bodies=Field<List<Transform>>(w,"bodies");Check(bodies.Count>0&&bodies.All(b=>b.position.x<.001f),"enemy warning must not cover the wall-hidden safe lobe");Bounds(w,a.position,center,r);
  foreach(var p in EnemyImpactRegion.Outline(a.position,center,r))Check(EnemyImpactRegion.Contains(a.position,center,p,r),"contour brackets actual reachable damage");
  foreach(float x in new[]{-1.4f,-.3f,.4f,1f,2f}){var p=new Vector3(x,0,0);var d=p-center;Check(EnemyImpactRegion.Contains(a.position,center,p,r)==PlayerUpgradeRules.IsInsideArea(d.x,d.z,r,WorldTraversal.HasGroundPath(a.position,p,.12f)),"preexisting hit predicate preserved");}
  var first=bodies.ToArray();var earth=Field<Material>(w,"earth");Call(w,"LateUpdate");Check(first.SequenceEqual(bodies),"unchanged warning retains body instances");float low=first[0].localScale.y;float initialHeat=first[0].GetComponent<Renderer>().PropertyBlock.Floats["_Heat"];w.SetProgress(1);Check(first[0].localScale.y>low&&first[0].GetComponent<Renderer>().PropertyBlock.Colors["_Color"].r>Field<Color>(w,"earthTint").r&&first[0].GetComponent<Renderer>().PropertyBlock.Floats["_Heat"]>initialHeat,"progress loads body height and material heat");
  var core=Field<Transform>(w,"interruptCore");w.SetInterruptible(true);Check(core.gameObject.activeSelf,"interrupt exposes crystal core");w.SetInterruptible(false);Check(!core.gameObject.activeSelf,"noninterruptible core hidden");
  GameSession.Instance=new GameSession{InputBlocked=true};WorldTraversal.Reset(ZoneKind.Dungeon);Call(w,"LateUpdate");Check(first.SequenceEqual(bodies),"pause retains loaded terrain bodies");GameSession.Instance.InputBlocked=false;Call(w,"LateUpdate");Check(first.All(b=>b.gameObject.Destroyed&&!b.gameObject.activeSelf)&&bodies.Any(b=>b.position.x>1),"cover revision retires old bodies and reveals newly reachable soil");Bounds(w,a.position,center,r);
  a.position=new Vector3(2,0,0);WorldTraversal.AddBox(Vector3.zero,new Vector2(.2f,7));Call(w,"LateUpdate");Check(bodies.All(b=>b.position.x>-.001f),"actual attacker move updates reachable side");
  var last=bodies.ToArray();var crystal=Field<Material>(w,"interruptMaterial");var owner=new EnemyController();owner.Bind(w);owner.CancelWarning();Check(owner.WarningCleared&&w.gameObject.Destroyed&&last.All(b=>b.gameObject.Destroyed)&&core.gameObject.Destroyed,"actual ClearWarning cancels full hierarchy");Check(earth.Destroyed&&crystal.Destroyed&&Enumerable.Range(0,3).All(v=>!EnemySkillPhysicalVfx.CrustMesh(v).Destroyed),"actual WorldResources disposes owned materials and preserves shared mesh");
  WorldTraversal.Reset(ZoneKind.Wilderness);WorldTraversal.SetRiver(new[]{new Vector3(-15,0,0),new Vector3(15,0,0)},2,new Rect(-1,-2,2,4));a.position=new Vector3(4,0,-2);center=new Vector3(4,0,0);Check(!EnemyImpactRegion.Contains(a.position,center,new Vector3(4,0,1.5f),3),"opposite river bank remains safe");var bank=EnemyImpactRegion.Outline(a.position,center,3);Check(bank.Count>0&&bank.All(p=>p.z<-.99f),"river contour retains reachable bank");a.position=new Vector3(0,0,-2);center=Vector3.zero;Check(EnemyImpactRegion.Contains(a.position,center,new Vector3(0,0,1.5f),3),"bridge retains actual damage lane");
  WorldTraversal.Reset(ZoneKind.Dungeon);a.position=new Vector3(12,0,11);a.position=WorldTerrain.Ground(a.position);Check(a.position.y>.1f,"fixture uses actual raised world terrain");var raised=EnemyAttackTelegraph.Circle(a.position,1.5f,a);Bounds(raised,a.position,a.position,1.5f);
  foreach(var factory in new Func<EnemyAttackTelegraph>[] {()=>EnemyAttackTelegraph.Melee(new Vector3(-3,0,0),new Vector3(-.5f,0,0),.7f),()=>EnemyAttackTelegraph.Charge(new Vector3(-3,0,0),new Vector3(-.5f,0,0),.8f),()=>EnemyAttackTelegraph.Fan(new Vector3(-3,0,0),new[]{Vector3.right},new[]{2.5f},.7f)}){WorldTraversal.Reset(ZoneKind.Dungeon);WorldTraversal.AddBox(Vector3.zero,new Vector2(.2f,7));var lane=factory();var points=Field<List<Vector3>>(lane,"points");Check(points.Count>0&&points.All(p=>p.x<-.1f&&WorldTraversal.HasGroundPath(new Vector3(-3,0,0),p,.12f)),"melee charge fan soil remain in actual reachable lane");UnityEngine.Object.Destroy(lane.gameObject);}
  return "PASS: "+checks+" actual enemy soil/Contains/terrain/progress/cache/cancel/resource checks (managed engine doubles)";
 }
}
